  "price.be.maths.none": "{price} ÷ {div} (bez VAT) − {cost} = {m} na sztukę ({item}): po VAT i składnikach nic nie zostaje.",
  "price.be.maths.any": "Przy dzisiejszej cenie {price} ÷ {div} (bez VAT) − {cost} = {m} na sztukę ({item}): każda sprzedaż już przynosi stratę, więc każda sprzedaż po nowej cenie jest lepsza.",
  "price.be.maths.rise": "{old} dziś ÷ {new} przy nowej cenie − 1 = {be} zmiany sprzedaży. {units} × {old} ÷ {new} = {level} tygodniowo utrzymuje Cię na tym samym poziomie, więc możesz sprzedawać do {n} sztuk mniej tygodniowo.",
  "price.be.maths.cut": "{old} dziś ÷ {new} przy nowej cenie − 1 = {be} zmiany sprzedaży. {units} × {old} ÷ {new} = {level} tygodniowo potrzeba, żeby zostać na tym samym poziomie, więc potrzebujesz {n} sztuk więcej tygodniowo.",
