  "price.be.plain.cut": "Przy cenie {price} każda sztuka ({item}) zostawia {new} po VAT i składnikach zamiast {old}, więc {words}. Jeśli sprzedasz mniej, wyjdziesz gorzej.",
  "price.worst.maths": "Ostrożny szacunek: {u} tygodniowo × {m} = {wn}; {wn} {vsOld} = {dw} tygodniowo; × {days} dni ÷ 7 = {wl}",
